import { createContext, useContext } from 'react';

/**
 * Which side of a split view a screen is drawn in, or `undefined` when it
 * has the window to itself (always, on a phone).
 *
 * A screen reads this for the few things that differ in a pane: it is not
 * the page's `<main>` (the split view owns that), and a page in the detail
 * pane does not need a back button when the list it came from is beside it.
 */
export type Pane = 'list' | 'detail' | undefined;

export const PaneContext = createContext<Pane>(undefined);

/** The pane this screen is drawn in, if it is in one. */
export function usePane(): Pane {
  return useContext(PaneContext);
}
